"""Render `reports/01-turn-audit.md` from the Stage 1 audit."""

from __future__ import annotations

import json
from pathlib import Path

from . import config as C
from .report import _table, _km, _pct


def _n(value) -> str:
    return f"{value:,}"


def write(a: dict, path: Path = C.TURN_REPORT_MD) -> Path:
    graph = a["graph"]
    restrictions = a["restrictions"]
    uturns = a["u_turns"]
    traps = a["traps"]
    scc = a["scc"]
    meta = a["meta"]

    parts: list[str] = ["# Stage 1 — turn-expanded graph L(G): audit\n"]
    parts.append(
        "Generated by `efficientroute stage1`. Every number is read from\n"
        "`data/derived/01-turn-stats.json`, which the Stage 1 gate asserts against.\n"
    )

    gate = "PASS" if scc["share_of_required_km"] >= 0.99 else "FAIL"
    parts.append("\n## Headline\n")
    parts.append(
        f"> ## L(G): **{_n(graph['nodes'])} nodes**, **{_n(graph['edges'])} legal manoeuvres**\n"
        f">\n"
        f"> The largest strongly connected component of **L** reaches\n"
        f"> **{_km(scc['required_km_reachable'])} km** of the "
        f"{_km(scc['required_km_total'])} km required traversal carried into this stage —\n"
        f"> **{scc['share_of_required_km'] * 100:.2f}%**. Gate (≥ 99%): **{gate}**.\n"
    )
    parts.append(
        "\nComponents are computed on **L**, not on the base network. That is the whole point of\n"
        "the check: an arc can be present and reachable in the base graph and still be a legal\n"
        "trap once turn restrictions apply — enterable, but not leavable.\n"
    )

    parts.append("\n## 1. Size of L\n")
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Nodes (directed arcs)", _n(graph["arc_nodes"])],
                ["Nodes (via-way restriction clones)", _n(graph["clone_nodes"])],
                ["**Nodes total**", f"**{_n(graph['nodes'])}**"],
                ["Manoeuvres before restrictions", _n(graph["edges_before_restrictions"])],
                ["**Manoeuvres after restrictions**", f"**{_n(graph['edges'])}**"],
                ["Mean out-degree", f"{graph['mean_out_degree']:.2f}"],
            ],
        )
    )
    parts.append("\n### Manoeuvres by turn class\n")
    total_edges = max(graph["edges"], 1)
    parts.append(
        _table(
            ["Turn class", "Manoeuvres", "% of L", "Penalty (s)"],
            [
                [
                    name,
                    _n(count),
                    _pct(count / total_edges * 100),
                    f"{graph['turn_penalty_s'].get(name, 0):.0f}",
                ]
                for name, count in graph["turn_class_counts"].items()
            ],
        )
    )
    parts.append(
        "\nPenalties are SPEC §3.3's own approximations, still marked **[CONFIRM values]** there.\n"
        "They live in `config.TURN_PENALTY_S` so Stage 2 can calibrate them without rebuilding L.\n"
    )

    parts.append("\n## 2. Turn restrictions\n")
    parts.append(
        _table(
            ["Stage", "Count"],
            [
                ["Found touching the network", _n(meta.get("restrictions_found", 0))],
                ["Parsed as binding on a car", _n(meta.get("restrictions_applicable", 0))],
                ["Skipped at parse time", _n(meta.get("restrictions_skipped", 0))],
                ["**Applied to L**", f"**{_n(restrictions['applied'])}**"],
                ["Resolved to no manoeuvre in L", _n(restrictions["unresolvable"])],
                ["— of which **via-way**", f"**{_n(restrictions['via_way'])}**"],
                ["— of which via-node", _n(restrictions["via_node"])],
                ["Manoeuvres removed", _n(restrictions["edges_removed_total"])],
                ["— by `no_*` relations", _n(restrictions["edges_removed_no"])],
                ["— by `only_*` relations", _n(restrictions["edges_removed_only"])],
                ["Forbidden manoeuvres already absent", _n(restrictions["edges_already_absent"])],
                ["Via-way clone nodes created", _n(restrictions["clones_created"])],
            ],
        )
    )
    parts.append("\n### By restriction type\n")
    parts.append(
        _table(
            ["Type", "Count"],
            [[f"`{k}`", _n(v)] for k, v in restrictions["by_type"].items()],
        )
    )
    if meta.get("restrictions_skipped_by_reason"):
        parts.append("\n### Skipped at parse time, with reason\n")
        parts.append(
            _table(
                ["Reason", "Count"],
                [[f"`{k}`", _n(v)] for k, v in meta["restrictions_skipped_by_reason"].items()],
                numeric=False,
            )
        )
    if restrictions["unresolvable_by_reason"]:
        parts.append("\n### Parsed but resolving to no manoeuvre\n")
        parts.append(
            _table(
                ["Reason", "Count"],
                [[f"`{k}`", _n(v)] for k, v in restrictions["unresolvable_by_reason"].items()],
                numeric=False,
            )
        )
        parts.append(
            "\nEvery one of these is a restriction that contradicts the one-way tagging of its own\n"
            "members: the `from` way never ends at the via node, or the `to` way never leaves it.\n"
            "Either the restriction or the `oneway` tag is wrong in OSM. They are logged with their\n"
            "relation ids in `data/derived/01-restrictions.csv`, not silently dropped.\n"
        )
    parts.append(
        f"\n**Via-way restrictions ({_n(restrictions['via_way'])}) are honoured exactly, by cloning "
        "the via arc.**\nA via-way constraint spans two manoeuvres, which a first-order edge-based "
        "graph cannot\nexpress. The clone is reachable only from the restriction's `from` arc and "
        "loses the\nforbidden continuation; the original keeps it for every other approach. Removing "
        "either\nedge instead would have been legal but would have deleted drivable manoeuvres and\n"
        "manufactured traps. Every L-node carries its physical `arc_id`, so Stage 3 groups coverage\n"
        "by arc and never double-counts a clone.\n"
    )

    parts.append("\n## 3. U-turn edges\n")
    parts.append("\n### Created by the §3.3 policy\n")
    parts.append(
        _table(
            ["Reason created", "Edges"],
            [[f"`{k}`", _n(v)] for k, v in sorted(uturns["by_reason"].items())]
            + [["**Total created**", f"**{_n(uturns['total'])}**"]],
        )
    )
    removed_by_restriction = uturns["total"] - uturns["reverse_arc_edges"]
    parts.append(
        f"\nOf those, **{_n(removed_by_restriction)}** were then deleted again by a `no_u_turn` "
        f"relation, leaving\n**{_n(uturns['reverse_arc_edges'])}** reverse-arc U-turns standing in L. "
        "The policy and the restrictions are\nindependent filters and both have to pass.\n"
    )
    parts.append("\n### Surviving in L, by kind\n")
    parts.append(
        "\n" + _table(
            ["Manoeuvre", "Edges", "Governed by the §3.3 U-turn policy?"],
            [
                ["Reverse-arc U-turn (`a → reverse(a)`)", _n(uturns["reverse_arc_edges"]), "yes"],
                ["Hairpin onto a *different* arc", _n(uturns["hairpin_edges"]), "no — an ordinary manoeuvre"],
            ],
            numeric=False,
        )
    )
    parts.append(
        f"\nThe turn-class table above counts {_n(uturns['reverse_arc_edges'] + uturns['hairpin_edges'])} "
        "manoeuvres as `u_turn` by bearing, but only\n"
        f"{_n(uturns['reverse_arc_edges'])} of them are reverse-arc U-turns. The other "
        f"{_n(uturns['hairpin_edges'])} double back onto a **different**\narc: switchbacks on the "
        "hillside roads of Mtatsminda and Vake, and the turnaround loops that link\nthe two "
        "carriageways of a dual. Those are ordinary legal manoeuvres that merely look like\n"
        "U-turns to a bearing test, and SPEC §3.3's policy does not govern them — it governs\n"
        "`a → reverse(a)`. Conflating the two would make the policy appear to have created "
        "thousands\nof edges it never touched.\n"
    )
    parts.append(
        "\nSPEC §3.3 requires reverse-arc U-turns to be *absent*\n"
        "where the manoeuvre is not physically possible, not merely penalised, so they are created\n"
        "only at a dead-end tip or where the carriageway carries positive evidence of room:\n"
        f"`width ≥ {uturns['min_width_m']} m` or `lanes ≥ {uturns['min_total_lanes']}`. SPEC leaves that "
        "threshold\n**[CONFIRM]**; §1.1 fixes the direction, because inventing a manoeuvre that cannot "
        "be driven\nbreaks invariant U1 while withholding one only costs deadhead. No U-turn edge "
        f"exists on\n{', '.join('`' + c + '`' for c in uturns['no_u_turn_classes'])}.\n"
    )

    parts.append("\n## 4. Traps\n")
    by_cause = traps.get("by_cause") or {}
    clip = by_cause.get("clip_boundary", {})
    genuine = by_cause.get("genuine", {})
    parts.append(
        _table(
            ["Cause", "No legal exit", "No legal entry", "km"],
            [
                [
                    "`clip_boundary` — the road continues past the extract",
                    _n(clip.get("no_legal_exit", 0)),
                    _n(clip.get("no_legal_entry", 0)),
                    _km(clip.get("km", 0.0)),
                ],
                [
                    "**`genuine` — needs fixing**",
                    f"**{_n(genuine.get('no_legal_exit', 0))}**",
                    f"**{_n(genuine.get('no_legal_entry', 0))}**",
                    _km(genuine.get("km", 0.0)),
                ],
                [
                    "Total",
                    _n(traps["no_legal_exit"]),
                    _n(traps["no_legal_entry"]),
                    _km(traps["no_legal_exit_km"] + traps["no_legal_entry_km"]),
                ],
            ],
            numeric=False,
        )
    )
    parts.append(
        "\nThe largest no-exit and no-entry arcs are trunk roads leaving the extract — the Tbilisi\n"
        "Bypass, the Senaki–Leselidze, the road to Marneuli — and they show up as a *matched pair*\n"
        "on the same way: the forward arc has no legal entry and the backward arc no legal exit,\n"
        "because the road simply continues past the 2 km clip buffer and SPEC §3.3 permits no\n"
        "U-turn on trunk. Those are artefacts of where the extract stops, not broken junctions.\n"
        "Listing them beside the real ones buries the handful that actually need attention.\n"
    )
    if traps.get("by_rule"):
        parts.append(
            "\nClassified by: "
            + ", ".join(
                f"`{rule or 'none'}` {count}" for rule, count in sorted(traps["by_rule"].items())
            )
            + f". Tolerance {C.CLIP_EDGE_TOLERANCE_M:.0f} m from the clip edge.\n"
        )

    genuine_rows = [r for r in traps["rows"] if r.get("trap_cause") == "genuine"]
    clip_rows = [r for r in traps["rows"] if r.get("trap_cause") == "clip_boundary"]

    # The mirror rule is sufficient on its own per the Stage 0b brief, but a
    # mirrored pair far from the clip edge is a real dead-end where no U-turn is
    # permitted, not an extract artefact. Do not let the label hide it.
    inland = [
        r for r in clip_rows
        if r.get("trap_cause_rule") == "mirrored_reverse"
        and (r.get("clip_edge_distance_m") or 0) > 1000.0
    ]
    if inland:
        parts.append(
            f"\n> **Caveat on {_n(len(inland))} of the clip-boundary rows.** They qualify on the "
            "mirror rule alone —\n"
            "> forward arc with no legal entry, backward arc with no legal exit at the same node —\n"
            "> yet sit "
            + ", ".join(
                f"{(r.get('clip_edge_distance_m') or 0) / 1000:.1f} km"
                for r in sorted(inland, key=lambda x: -(x.get("clip_edge_distance_m") or 0))[:4]
            )
            + " inside the clip. Those are genuine dead-ends where SPEC §3.3\n"
            "> permits no U-turn (trunk and motorway class), not artefacts of where the extract\n"
            "> stops. The mirror rule is what the Stage 0b brief specifies, so the classification\n"
            "> stands as written; this note is here so the rows are not lost behind the label:\n"
            + "".join(
                f">\n> - `{r['arc_id']}` {r['highway_class']} — {r['name'] or 'unnamed'} "
                f"({(r.get('clip_edge_distance_m') or 0) / 1000:.1f} km inland)"
                for r in sorted(inland, key=lambda x: -(x.get("clip_edge_distance_m") or 0))
            )
            + "\n"
        )

    parts.append(f"\n### 4.1 Genuine traps ({_n(len(genuine_rows))}) — the list that matters\n")
    if genuine_rows:
        parts.append(
            _table(
                ["Kind", "arc_id", "Class", "Name", "m", "Dangling node", "km to clip edge"],
                [
                    [
                        f"`{r['kind']}`",
                        f"`{r['arc_id']}`" + (f" (clone {r['variant']})" if r["variant"] else ""),
                        r["highway_class"],
                        r["name"] or "—",
                        f"{r['length_m']:.0f}",
                        str(r.get("dangling_node", "")),
                        f"{(r.get('clip_edge_distance_m') or 0) / 1000:.1f}",
                    ]
                    for r in genuine_rows
                ],
                numeric=False,
            )
        )
        parts.append(
            "\nUnder SPEC §1.1 these are to be resolved, not dropped. Most are short service or\n"
            "residential stubs where the one-way tagging leaves no legal way back out; each is a\n"
            "candidate OSM fix rather than a modelling change.\n"
        )
    else:
        parts.append("\nNone.\n")

    parts.append(f"\n### 4.2 Clip-boundary traps ({_n(len(clip_rows))}) — artefacts of the extract\n")
    if clip_rows:
        shown = clip_rows[:25]
        parts.append(
            _table(
                ["Kind", "arc_id", "Class", "Name", "m", "km to clip edge"],
                [
                    [
                        f"`{r['kind']}`",
                        f"`{r['arc_id']}`",
                        r["highway_class"],
                        r["name"] or "—",
                        f"{r['length_m']:.0f}",
                        f"{(r.get('clip_edge_distance_m') or 0) / 1000:.1f}",
                    ]
                    for r in shown
                ],
                numeric=False,
            )
        )
        if len(clip_rows) > len(shown):
            parts.append(
                f"\n*{_n(len(clip_rows) - len(shown))} further clip-boundary traps omitted here; "
                "all of them are in `data/derived/01-traps.csv`.*\n"
            )
    else:
        parts.append("\nNone.\n")

    parts.append("\n## 5. Strong components of L\n")
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Components", _n(scc["component_count"])],
                ["Largest component — nodes", _n(scc["largest_node_count"])],
                ["Largest component — share of nodes", _pct(scc["largest_share_of_nodes"] * 100)],
                ["Required traversal km carried in", _km(scc["required_km_total"])],
                ["**Reachable inside the largest component**", f"**{_km(scc['required_km_reachable'])}**"],
                ["**Share of required km**", f"**{_pct(scc['share_of_required_km'] * 100)}**"],
                ["Required km lost", _km(scc["required_km_lost"])],
                ["Arcs outside the largest component", _n(scc["lost_arc_count"])],
                ["Their arc km", _km(scc["lost_arc_km"])],
            ],
        )
    )
    if scc["lost_by_class"]:
        parts.append("\n### Lost arcs by class\n")
        parts.append(
            _table(
                ["Class", "Arcs", "Arc km"],
                [[r["highway_class"], _n(r["arc_count"]), _km(r["arc_km"])] for r in scc["lost_by_class"]],
            )
        )
    if a.get("loss_causes"):
        parts.append("\n### Lost arcs by cause\n")
        parts.append(
            _table(
                ["Cause", "Arcs", "Arc km"],
                [
                    [f"`{r['cause']}`", _n(r["arc_count"]), _km(r["arc_km"])]
                    for r in a["loss_causes"]
                ],
                numeric=False,
            )
        )
        parts.append(
            "\nCauses are established by counterfactual rebuilds, not guessed: an arc attributed to\n"
            "`turn_restrictions` returns to the largest component when restrictions are dropped, one\n"
            "attributed to `u_turn_policy` returns under a permissive U-turn rule, and so on.\n"
            "`clip_buffer_edge` means the arc lies only in the 2 km buffer outside the municipality —\n"
            "an edge-of-extract artefact rather than a Tbilisi problem.\n"
        )

    parts.append("\n## 6. Required arcs that became unreachable\n")
    parts.append(
        f"Stage 0 handed over {_km(scc['required_km_total'])} km of required traversal on "
        f"{_n(meta.get('routable_arcs', 0))} routable arcs.\nApplying turn restrictions and the "
        f"§3.3 U-turn policy strands **{_n(scc['lost_arc_count'])} of them**, worth\n"
        f"**{_km(scc['required_km_lost'])} km** of required traversal.\n"
    )
    parts.append(
        "\n> **Under SPEC §1.1 these are to be *resolved*, not dropped.** Accuracy is the hard\n"
        "> constraint and efficiency is the objective subject to it, so an unreachable required arc\n"
        "> is a problem to solve before Stage 5 — by fixing the OSM data, by relaxing a threshold\n"
        "> that measurement shows to be wrong, or by widening the clip. It is not a rounding error,\n"
        "> and it is not permission to reduce the coverage target.\n"
    )
    if a.get("lost_detail"):
        parts.append("\nEvery unreachable required arc, with its cause:\n")
        parts.append(
            _table(
                ["arc_id", "Class", "Name", "m", "passes", "Cause"],
                [
                    [
                        f"`{r['arc_id']}`",
                        r["highway_class"],
                        r["name"] or "—",
                        f"{r['length_m']:.0f}",
                        str(r["min_passes"]),
                        f"`{r['cause']}`",
                    ]
                    for r in a["lost_detail"]
                ],
                numeric=False,
            )
        )

    parts.append(_spotchecks(a))
    parts.append(_decisions(a))

    parts.append("\n## Provenance\n")
    parts.append(
        _table(
            ["Item", "Value"],
            [
                ["Base network", "`data/derived/network.gpkg` layer `arcs` (Stage 0)"],
                ["Restriction source", f"`{meta.get('pbf_path', '')}`"],
                ["Graph", "`data/derived/turn_graph.pkl`"],
                ["Applied restrictions log", "`data/derived/01-restrictions.csv`"],
                ["Parse-time skips", "`data/derived/01-restrictions-unparsed.csv`"],
                ["Traps", "`data/derived/01-traps.csv`"],
                ["Map", "`reports/01-turn-graph.html`"],
                ["Junction spot-checks", "`surveys/01-junction-spotchecks.json`"],
                ["Runtime", f"{meta.get('runtime_s', 0)} s"],
            ],
            numeric=False,
        )
    )
    text = "\n".join(parts) + "\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    return path


def _spotchecks(a: dict) -> str:
    rows = a.get("spotchecks") or []
    out = ["\n## 7. Manual spot-check — 20 junctions against satellite imagery\n"]
    if not rows:
        out.append(
            "\n**Not yet performed.** The gate requires 20 junctions verified against imagery;\n"
            "automated tests cannot catch a restriction that OSM simply does not have.\n"
        )
        return "".join(out)

    verdicts: dict[str, int] = {}
    for r in rows:
        verdicts[r["verdict"]] = verdicts.get(r["verdict"], 0) + 1
    out.append(
        "\nAutomated tests can only prove that L honours the restrictions OSM records. They cannot\n"
        "catch a restriction that OSM does not have at all, which is why this table exists. Each\n"
        "junction was read off Esri World Imagery at the coordinates given and compared with the\n"
        "manoeuvres L actually permits.\n"
        "\n**What this check can and cannot catch.** Overhead imagery shows *physical* constraints —\n"
        "medians, splitter islands, kerb lines, dedicated turnaround loops, carriageway width. It\n"
        "does not show *signage*, so a signed no-left-turn that OSM has not recorded is invisible to\n"
        "it. A junction marked `confirmed` below means the manoeuvres L permits and bans are\n"
        "consistent with the physical layout, not that OSM's restriction set is proven complete.\n"
        "Closing that gap needs street-level imagery or a survey, and is worth doing before Stage 5\n"
        "commits a driver to a route.\n"
    )
    out.append(
        "\nJunctions were chosen deterministically: the 12 carrying a via-way relation first, since\n"
        "those are the ones a naive implementation gets wrong, then the busiest restricted junctions\n"
        "by count, with the landmark categories the stage brief names (Heroes' Square, riverside\n"
        "embankment, central couplets) snapped to the nearest restricted junction. Names below are\n"
        "the street names actually found at each node, not the landmark that selected it.\n"
    )
    out.append("\n" + _table(["Verdict", "Junctions"], [[f"`{k}`", str(v)] for k, v in sorted(verdicts.items())], numeric=False))
    out.append("\n\n" + _table(
        ["#", "Junction", "lon, lat", "What L permits", "What the imagery shows", "Verdict"],
        [
            [
                str(r["id"]),
                r["name"],
                f"{r['lon']:.5f}, {r['lat']:.5f}",
                r["graph_says"],
                r["imagery"],
                f"**{r['verdict']}**",
            ]
            for r in rows
        ],
        numeric=False,
    ))
    out.append("\n")
    return "".join(out)


def _decisions(a: dict) -> str:
    meta = a["meta"]
    variants = a.get("mainline_variants") or []
    out = ["\n## 8. Where this stage departs from SPEC, and why\n"]

    if variants:
        out.append(
            "\n### SPEC §3.3: \"Motorway and trunk nodes … are enterable only via ramp arcs\"\n"
        )
        out.append(
            "\nThat clause is written for grade-separated roads. In Tbilisi, `highway=trunk` is an\n"
            "at-grade arterial class — Stage 0 measured 446 two-way trunk segments with ordinary\n"
            "junctions. Applying the clause to trunk deletes real, drivable manoeuvres. Measured\n"
            "both ways:\n"
        )
        out.append("\n" + _table(
            ["Mainline classes", "Manoeuvres in L", "SCC share of required km", "Required km lost", "Gate ≥ 99%"],
            [
                [
                    ", ".join(f"`{c}`" for c in v["classes"]) or "(none)",
                    _n(v["edges"]),
                    _pct(v["share_of_required_km"] * 100),
                    _km(v["required_km_lost"]),
                    "PASS" if v["share_of_required_km"] >= 0.99 else "**FAIL**",
                ]
                for v in variants
            ],
            numeric=False,
        ))
        out.append(
            f"\n**Decision: the rule is applied to `motorway` only**, which is what the current graph\n"
            f"carries ({', '.join('`' + c + '`' for c in meta.get('mainline_entry_via_ramps_only', [])) or 'none'}).\n"
            "Extending it to trunk as the spec's wording implies fails the Stage 1 gate outright.\n"
            "This is flagged rather than resolved silently: the wording assumes a road class that\n"
            "Tbilisi's data does not match, and SPEC should be amended to say *grade-separated*\n"
            "mainlines rather than naming trunk. Note also that OSM already encodes grade separation\n"
            "topologically — a bridge does not share a node with the road beneath it — so for\n"
            "correctly mapped junctions the rule is close to a no-op and mostly removes connections\n"
            "the data says are real.\n"
        )

    out.append("\n### SPEC §3.3 edge cost vs SPEC §11 stage order\n")
    out.append(
        "\nSPEC §3.3 defines an edge cost as *traversal time of `b` + turn penalty*, but SPEC §11\n"
        "places the time model in Stage 2. Rather than resolve that silently in either direction,\n"
        "L carries the two components **separately**: the turn penalty is a real Stage 1 product,\n"
        "and traversal time comes from an explicitly provisional speed model — posted `maxspeed`\n"
        "where tagged, a free-flow-by-class table otherwise, capped at the 40 km/h capture speed\n"
        "except on the reduced-quality motorway and trunk arcs of §3.2. No congestion, no gradient,\n"
        "no idle allowance. Stage 2 replaces one function and does not rebuild the graph.\n"
    )
    out.append("\n### Thresholds this stage was measured against\n")
    out.append("\n" + _table(
        ["Constant", "Value", "SPEC status"],
        [
            ["`TURN_PENALTY_S`", str(a["graph"]["turn_penalty_s"]), "§3.3 **[CONFIRM values]**"],
            ["`U_TURN_MIN_WIDTH_M`", f"{a['u_turns']['min_width_m']} m", "§3.3 **[CONFIRM]**"],
            ["`U_TURN_MIN_TOTAL_LANES`", str(a["u_turns"]["min_total_lanes"]), "chosen here, reported"],
            ["`TURN_STRAIGHT_MAX_DEG`", f"{C.TURN_STRAIGHT_MAX_DEG}°", "chosen here, reported"],
            ["`TURN_UTURN_MIN_DEG`", f"{C.TURN_UTURN_MIN_DEG}°", "chosen here, reported"],
            ["`BEARING_SAMPLE_M`", f"{C.BEARING_SAMPLE_M} m", "chosen here, reported"],
        ],
        numeric=False,
    ))
    out.append("\n")
    return "".join(out)


def load_spotchecks(path: Path = C.SPOTCHECK_PATH) -> list[dict]:
    if not Path(path).exists():
        return []
    return json.loads(Path(path).read_text())
